```python
def to_int(s):
    vals = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
    total = 0
    prev_value = 0
    for c in reversed(s):
        value = vals[c]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total
